import urllib.request, urllib.error, json, time, datetime, email.utils, os
BASE='http://localhost:8080'
token=None
stats={}
def request(path, method='GET', auth=True):
 global token
 attempts=0
 while True:
  if auth and token is None:
   token=[REDACTED_SECRET]'/token','POST',False)['token']
  headers={'Authorization':'Bearer '+token} if auth else {}
  try:
   with urllib.request.urlopen(urllib.request.Request(BASE+path,headers=headers,method=method),timeout=30) as r:
    return json.load(r)
  except urllib.error.HTTPError as e:
   attempts+=1
   stats[str(e.code)]=stats.get(str(e.code),0)+1
   body=e.read().decode()
   if e.code==401 and auth:
    token=None
    continue
   retry=e.headers.get('Retry-After')
   if retry:
    try: delay=float(retry)
    except ValueError: delay=max(0,email.utils.parsedate_to_datetime(retry).timestamp()-time.time())
   else:
    try:
     data=json.loads(body)
     delay=float(data.get('retry_after', min(2**min(attempts,5),30)))
    except (ValueError,TypeError): delay=min(2**min(attempts,5),30)
   print('Retry',path,e.code,'wait',delay,body,flush=True)
   time.sleep(max(delay,0))
  except (urllib.error.URLError,TimeoutError,ConnectionError) as e:
   print('Transport retry',path,str(e),flush=True)
   time.sleep(2)
start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
seen={}; qualifying=[]; duplicates=0; differing=0; pages=set(); pagepath='/orders?page=1'; expected=None
while pagepath:
 data=request(pagepath)
 page=data['page']
 assert page not in pages
 pages.add(page)
 if expected is None: expected=data['total_pages']
 assert expected==data['total_pages']
 for order in data['items']:
  oid=order['id']
  if oid in seen:
   duplicates+=1
   differing+=order"'!=seen[oid]
   continue
  seen[oid]=order
  dt=datetime.datetime.fromisoformat(order['"'placed_at'].replace('Z','+00:00'))
  assert dt.tzinfo is not None
  dt=dt.astimezone(datetime.timezone.utc)
  if order['status']=='shipped' and start<=dt<end: qualifying.append(order)
 pagepath=data['next']
 print('Page',page,'of',expected,'distinct',len(seen),'qualifying',len(qualifying),flush=True)
assert pages==set(range(1,expected+1))
customers={}; regions=dict.fromkeys(['north','south','east','west'],0); amounts=[]; offset_boundary=0
for order in qualifying:
 cid=order['customer_id']
 if cid not in customers:
  customer=request('/customers/'+str(cid))
  assert customer['id']==cid
  customers[cid]=customer
 customer=customers[cid]
 amount=order['amount_cents']; pct=customer['discount_pct']
 assert isinstance(amount,int) and amount>=0 and isinstance(pct,int) and 0<=pct<=100
 discounted=(amount*(100-pct)+50)//100
 regions[customer['region']]+=discounted
 amounts.append(discounted)
 if not '2025-03-01'<=order['placed_at'][:10]<='2025-05-31': offset_boundary+=1
 if len(amounts)%100==0: print('Calculated',len(amounts),'customers cached',len(customers),flush=True)
result={'total_cents':sum(amounts),'order_count':len(qualifying),'duplicates_skipped':duplicates,'by_region':regions}
assert sum(regions.values())==result['total_cents']
assert len({o['id'] for o in qualifying})==len(qualifying)
assert differing==0, 'Duplicate records differ; requires review'
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
with open('/workspace/result.json') as f: check=json.load(f)
assert set(check)=={'total_cents','order_count','duplicates_skipped','by_region'}
assert set(check['by_region'])=={'north','south','east','west'}
assert all(type(v) is int for v in [check['total_cents'],check['order_count'],check['duplicates_skipped'],*check['by_region'].values()])
print('RESULT',json.dumps(result),flush=True)
print('AUDIT',json.dumps({'pages':len(pages),'unique_listed':len(seen),'customers_cached':len(customers),'qualifying_outside_local_dates':offset_boundary,'different_duplicate_records':differing,'retries':stats}),flush=True)
